// ===== 拆出推薦紀錄 =====
// 把當日報告的首選標的與觀察名單拆成 recommendations 的資料列
// 接在既有的「Code in JavaScript」節點之後，與 LINE / Sheets / Supabase 三條並行

const items = $input.all();
const sheetsItem = items.find(i => i.json.type === 'sheets');
if (!sheetsItem) {
  throw new Error('[拆出推薦紀錄] 上游找不到 type=sheets 的項目');
}

const data = sheetsItem.json.data || {};
const reportDate = data.date;
if (!reportDate) {
  throw new Error('[拆出推薦紀錄] 報告 JSON 缺少 date 欄位');
}

// ---------- 報價表：補齊觀察名單缺少的進場價 ----------
const quoteBySymbol = {};
try {
  ($('整合報價').first().json.stockQuotes || []).forEach(q => {
    if (q && q.symbol) quoteBySymbol[String(q.symbol).toUpperCase()] = Number(q.price);
  });
} catch (e) {
  console.log('[拆出推薦紀錄] 取不到「整合報價」，觀察名單進場價改用報告內的報價');
}

// ---------- 題材內的個股資訊 ----------
const themeStock = {};
(data.themes || []).forEach(t => {
  (t.stocks || []).forEach(s => {
    const sym = String(s?.symbol || '').trim().toUpperCase();
    if (!sym) return;
    themeStock[sym] = {
      price: Number(s.price) > 0 ? Number(s.price) : null,
      theme: t.name || null,
      heat:  t.heat || null,
    };
  });
});

// ---------- 工具 ----------
const VALID_SYMBOL = /^[A-Z][A-Z.\-]{0,5}$/;
const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : null;
};
const str = (v) => {
  const s = String(v ?? '').trim();
  return s || null;
};

const rows = [];

// ---------- 首選標的 ----------
const p = data.primary_pick;
if (p && VALID_SYMBOL.test(String(p.symbol || '').trim().toUpperCase())) {
  const sym = String(p.symbol).trim().toUpperCase();
  rows.push({
    report_date:  reportDate,
    symbol:       sym,
    role:         'primary',
    theme:        str(p.theme) || themeStock[sym]?.theme || null,
    entry_price:  num(p.price) || quoteBySymbol[sym] || null,
    target_price: num(p.target),
    stop_loss:    num(p.stop_loss),
    confidence:   str(p.confidence),
    hold_period:  str(p.hold_time),
    heat:         str(p.heat) || themeStock[sym]?.heat || null,
    reason:       str(p.reason),
    note:         str(p.entry_timing),
    model:        'claude',
  });
} else {
  // symbol 是「N/A」「暫不推薦」這類值，代表今天沒有首選標的，不寫入
  console.log('[拆出推薦紀錄] 今日無有效首選標的：', String(p?.symbol ?? '(缺欄位)'));
}

// ---------- 觀察名單 ----------
(data.watchlist || []).forEach(w => {
  const sym = String(w?.symbol || '').trim().toUpperCase();
  if (!VALID_SYMBOL.test(sym)) return;
  if (rows.some(r => r.symbol === sym && r.role === 'watchlist')) return;

  rows.push({
    report_date:  reportDate,
    symbol:       sym,
    role:         'watchlist',
    theme:        themeStock[sym]?.theme || null,
    entry_price:  themeStock[sym]?.price || quoteBySymbol[sym] || null,
    target_price: null,
    stop_loss:    null,
    confidence:   null,
    hold_period:  null,
    heat:         themeStock[sym]?.heat || null,
    reason:       null,
    note:         str(w.note),
    model:        'claude',
  });
});

if (!rows.length) {
  console.log('[拆出推薦紀錄] 今日無任何可記錄的推薦，不寫入');
  return [];
}

console.log(
  `[拆出推薦紀錄] ${reportDate} 寫入 ${rows.length} 筆：`,
  rows.map(r => `${r.role === 'primary' ? '首選' : '觀察'}:${r.symbol}`).join(', ')
);

return rows.map(json => ({ json }));
